SELECT c.c_customer_id, c.c_first_name, c.c_last_name, hd.hd_buy_potential, sm.sm_type, COUNT(*) AS order_count, AVG(cs.cs_net_profit) AS avg_profit, CASE WHEN AVG(cs.cs_net_profit) > 2000 THEN 'High' WHEN AVG(cs.cs_net_profit) > 1000 THEN 'Medium' ELSE 'Low' END AS profit_category FROM catalog_sales cs JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk WHERE cs.cs_ship_date_sk BETWEEN 2450000 AND 2453650 GROUP BY c.c_customer_id, c.c_first_name, c.c_last_name, hd.hd_buy_potential, sm.sm_type HAVING COUNT(*) >= 5 ORDER BY avg_profit DESC LIMIT 15
